    "text": "# This .gitignore file should be placed at the root of your Unity project directory\n#\n# Get latest from https://github.com/github/gitignore/blob/main/Unity.gitignore\n#\n# Recommended: add any editor/OS/tool-specific ignore rules from the Global/ templates as needed.\n# See: https://github.com/github/gitignore/tree/main/Global\n#\n.utmp/\n/[Ll]ibrary/\n/[Tt]emp/\n/[Oo]bj/\n/[Bb]uild/\n/[Bb]uilds/\n/[Ll]ogs/\n/[Uu]ser[Ss]ettings/\n*.log\n\n# Memory Profiler generated files\n# MemoryCaptures can get excessive in size\n# They also could contain extremely sensitive data\n/[Mm]emory[Cc]aptures/\n\n# Recordings can get excessive in size\n/[Rr]ecordings/\n\n# Uncomment this line if you wish to ignore the asset store tools plugin\n# /[Aa]ssets/AssetStoreTools*\n\n# Autogenerated Jetbrains Rider plugin\n/[Aa]ssets/Plugins/Editor/JetBrains*\n# Jetbrains Rider personal-layer settings\n*.DotSettings.user\n\n# Visual Studio cache directory\n.vs/\n\n# Gradle cache directory\n.gradle/\n\n# Autogenerated VS/MD/Consulo solution and project files\nExportedObj/\n.consulo/\n*.csproj\n*.unityproj\n*.sln\n*.slnx\n*.suo\n*.tmp\n*.user\n*.userprefs\n*.pidb\n*.booproj\n*.svd\n*.pdb\n*.mdb\n*.opendb\n*.VC.db\n\n# Unity3D generated meta files\n*.pidb.meta\n*.pdb.meta\n*.mdb.meta\n\n# Unity3D generated file on crash reports\nsysinfo.txt\n\n# Mono auto generated files\n.dirstamp\nmono_crash.*\ntmpinst-dir.stamp\n\n# Builds\n/*_BackUpThisFolder_ButDontShipItWithYourGame/\n/*_BurstDebugInformation_DoNotShip/\n*.apk\n*.aab\n*.obb\n*.unitypackage\n*.unitypackage.meta\n*.app\n\n# Crashlytics generated file\ncrashlytics-build.properties\n\n# Blender generated backup files\n/[Aa]ssets/**/*.blend1\n/[Aa]ssets/**/*.blend1.meta\n\n# TouchDesigner generated cache files\n/[Aa]ssets/**/TDImportCache/\n/[Aa]ssets/**/TDImportCache.meta\n\n# Unity Crash Recovery generated files\n/[Aa]ssets/_Recovery/\n/[Aa]ssets/_Recovery.meta\n\n# Addressables default ignores, before user customizations\n# By default, Addressables content builds will generate addressables_content_state.bin\n# files in platform-specific subfolders, for example:\n# /Assets/AddressableAssetsData/OSX/addressables_content_state.bin\n/[Aa]ssets/AddressableAssetsData/*/addressables_content_state.bin\n/[Aa]ssets/AddressableAssetsData/*/addressables_content_state.bin.meta\n/[Aa]ssets/AddressableAssetsData/link.xml\n/[Aa]ssets/AddressableAssetsData/link.xml.meta\n/[Aa]ssets/Addressables_Temp/\n/[Aa]ssets/Addressables_Temp.meta\n/[Aa]ssets/StreamingAssets/aa/\n/[Aa]ssets/StreamingAssets/aa.meta\n/ServerData/\n\n# EDM4U generated files\n/[Aa]ssets/GeneratedLocalRepo/\n/[Aa]ssets/GeneratedLocalRepo.meta\n\n# Android Gradle generated files\n/[Aa]ssets/Plugins/Android/**/*.gradle.backup*\n/[Aa]ssets/Plugins/Android/**/local.properties\n\n# Test Framework generated files\n/[Aa]ssets/Resources/PerformanceTestRunInfo.json\n/[Aa]ssets/Resources/PerformanceTestRunInfo.json.meta\n/[Aa]ssets/Resources/PerformanceTestRunSettings.json\n/[Aa]ssets/Resources/PerformanceTestRunSettings.json.meta\n/[Aa]ssets/InitTestScene*.unity\n/[Aa]ssets/InitTestScene*.unity.meta\n\n# Visual Scripting auto-generated files\n/[Aa]ssets/Unity.VisualScripting.Generated/VisualScripting.Core/Property Providers/\n/[Aa]ssets/Unity.VisualScripting.Generated/VisualScripting.Core/Property Providers.meta\n/[Aa]ssets/Unity.VisualScripting.Generated/VisualScripting.Flow/UnitOptions.db\n/[Aa]ssets/Unity.VisualScripting.Generated/VisualScripting.Flow/UnitOptions.db.meta\n\n# UI Toolkit auto generated files\n/UIElementsSchema/\n\n# Auto-generated cache in Assets folder\n/[Aa]ssets/[Ss]ceneDependencyCache*"
